function UIDirectDrawDialog:OnClickBtnOneNodeHandler()
    if isNull(self._rewardContentScr) then
        return
    end

    local homeDojo = self._directDrawComponent:GetDirectDrawHomeDojo()
    local currencyCount = GoodsUtils.GetThingNo(self._activityDojo.currency.id)
    local isEnough = currencyCount >= checkNumber(homeDojo.poolInfo.oneConsume.num)
    if isEnough then
        self:DrawRewards(self.drawType.OneDraw)
    else
        ActivityDirectDrawMgr:ExchangeActivityCurrency(self.drawType.OneDraw, function(consumeId, needPay)
            self:DrawRewards(self.drawType.OneDraw, consumeId, needPay)
        end)
    end
end

function UIDirectDrawDialog:OnClickBtnTenNodeHandler()
    if isNull(self._rewardContentScr) then
        return
    end
    local homeDojo = self._directDrawComponent:GetDirectDrawHomeDojo()
    local currencyCount = GoodsUtils.GetThingNo(self._activityDojo.currency.id)
    local isEnough = currencyCount >= checkNumber(homeDojo.poolInfo.tenConsume.num)
    if isEnough then
        self:DrawRewards(self.drawType.TenDraw)
    else
        ActivityDirectDrawMgr:ExchangeActivityCurrency(self.drawType.TenDraw, function(consumeId, needPay)
            if currencyCount > 0 then
                self:ConsumeCost(self._activityDojo.currency.id, currencyCount)
            end
            self:DrawRewards(self.drawType.TenDraw, consumeId, needPay)
        end)
    end
end
