---@param currencyId string 提取消耗的活动货币ID
---@param count number 提取消耗的活动货币数量
function UIDirectDrawDialog:DrawRewards(drawType, consumeId, needPay)
    CfUtils.PlayAnimation(self.Container, "ActivityDirectDrawMainDialog11200101_Extract")
    ActivityDirectDrawMgr:StartDrawReq(self._directDrawComponent:GetActivityDojo().id, drawType, function(jsonData)
        CfUtils.StartCoroutineWithBlocker(function()
            cs_coroutine.yield_return(WaitForSeconds(2))

            --- 获得奖励逻辑
            GoodsUtils.DrawRewards(jsonData.rewards, true)
            UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = jsonData.rewards, ignoreSort = true } })

            --- 扣除货币逻辑
            local _consumeCount = needPay
            if isNull(consumeId) then
                consumeId = self._directDrawComponent:GetActivityDojo().currency.id
                _consumeCount = self.config.currencyCount[drawType]
            end

            self:ConsumeCost(consumeId, _consumeCount)
            Events.Broadcast(Constants.EventNames.ActivityDirectDrawStartDrawReqUpdate)
        end)
    end)
end

---ConsumeCost  扣除用户背包中货币道具
---@param currencyId string 货币ID
---@param count number 货币数量
function UIDirectDrawDialog:ConsumeCost(currencyId, count)
    local consumes = {}
    table.insert(consumes, {
        goodsId = currencyId,
        num = -count
    })
    GoodsUtils.DrawRewards(consumes, true)
end

function UIDirectDrawDialog:RefreshDrawNumber()
    local TextDesc = self.DrawNumber.transform:Find("TextDesc")

    local homeDojo = self._directDrawComponent:GetDirectDrawHomeDojo()
    CfUtils.FillText(TextDesc, localize("每_num1_次召唤可获得_num2_点研究值。研究值达到_num3_点必得指定SSR", {_num1_ = homeDojo.poolInfo.drawTimes, _num2_ = homeDojo.poolInfo.drawNum, _num3_ = homeDojo.poolInfo.upperLimit}))

    ---@Todo FillData
    local Number = self.DrawNumber.transform:Find("Number")
    local allCount = homeDojo.poolInfo.upperLimit
    local currentCount = math.min(allCount, homeDojo.point)

    if allCount <= 0 then
        return
    end
    local TextNumber = Number.transform:Find("TextNumber")
    CfUtils.FillText(TextNumber, string.format("%d/%d", currentCount, allCount))
    if currentCount >= 0 then
        local Slider = Number.transform:Find("Slider")
        CfUtils.SetActive(Slider, true)
        local image = CfUtils.GetOrAddComponent(Slider, typeof(CS.UnityEngine.UI.Image))
        image.fillAmount = currentCount / allCount
    end
end

