function UIDirectDrawDialog:ConventSecondToTimeStamp(seconds)
    seconds = checkNumber(seconds)
    ---@type PlayerComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    local curTime = comp:GetPlayerDojo():GetServerTime()
    curTime = curTime or os.time()
    return seconds + curTime
end

function UIDirectDrawDialog:RefreshTitleGroup()
    ---@type ActivityDirectDrawComponent
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityDirectDrawComponent)
    local activityDojo = comp:GetActivityDojo()
    local url = activityDojo.titleImage
    if not string.isEmpty(url) then
        CfUtils.FillWebRawImage(self.ImgTitle, comp:GetActivityDojo().titleImage)
    end

    local TextTime = self.TitleGroup.transform:Find("TimeNode/TextTime")

    local startTime = self:ConventSecondToTimeStamp(activityDojo.startTime)
    local endTime = self:ConventSecondToTimeStamp(activityDojo.endTime)
    CfUtils.FillText(TextTime, os.date("%m/%d %H:%M", startTime) .. "-" .. os.date("%m/%d %H:%M", endTime))
end

