function UIDirectDrawDialog:CreateSpine(spinePath, parent)
    local loader = ResourceModule.LoadBundleSync(spinePath, nil, true)
    local skeletonDataAsset = nil
    if loader.IsSuccess then
        skeletonDataAsset = loader.ResultObject
        skeletonDataAsset = CS.UnityEngine.Object.Instantiate(skeletonDataAsset)
        local spine = SkeletonGraphic.NewSkeletonGraphicGameObject(skeletonDataAsset, parent)
        loader:Retain(spine)
        CfUtils.PlaySpine(spine, "animation", true)
    end
    loader:Release()
end

