function UIDirectDrawDialog:RefreshAttributeInfo()
    local homeDojo = self._directDrawComponent:GetDirectDrawHomeDojo()
    ---@type CardVo
    local vo = CfUtils.GetCfVo(AutoIds.IdSetting28, "CardVo", homeDojo.poolInfo.cardId)
    local attribute = vo.attributeType

    local row = CfUtils.GetCfLine(AutoIds.IdSetting61, attribute)
    local name = CS.ParseUtils.ParseLocalizeText(row, "name")
    local desc = CS.ParseUtils.ParseLocalizeText(row, "restrain")

    CfUtils.FillText(self.AttributeTextName, name)
    CfUtils.FillText(self.AttributeTextDesc, desc)
    --local switchImage = CfUtils.GetOrAddComponent(self.BtnAttribute.transform:Find("ImgAttribute").gameObject, CS.Game.Native.Common.UISwitchImage)
    CfUtils.SetUISwitchImage(self.BtnAttribute.transform:Find("ImgAttribute").gameObject, attribute)

    SetButtonAction(self.BtnAttribute, function(event)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UIBattlingAttributeCircleDialog })
    end)
end

function UIDirectDrawDialog:RefreshSlogan()
